function validate(input) {
  const [{ Users = [], Rides = [] }] = input;
  const users = new Set(), rides = new Set();
  for (const [id, name] of Users) {
    if (id === null || name === null) return 'user_id and name cannot be null.';
    if (users.has(id)) return `user_id ${id} appears twice in Users.`;
    users.add(id);
  }
  for (const [id, user, distance] of Rides) {
    if (id === null || user === null || distance === null) return 'ride_id, user_id and distance cannot be null.';
    if (rides.has(id)) return `ride_id ${id} appears twice in Rides.`;
    if (distance < 0) return 'distance cannot be negative.';
    rides.add(id);
  }
  return null;
}

