function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Addison', 'Ethan', 'Michael', 'Avery', 'Eleanor', 'Avery', 'Ethan'];
  const Users = [], Rides = [];
  if (size === 'small') {
    // A shuffled pool of ids 1..10; rides may also point at ids 11 and 12, which no user has.
    const ids = Array.from({ length: 10 }, (_, i) => i + 1);
    for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
    const count = Math.floor(rand() * 7);
    for (let i = 0; i < count; i++) Users.push([ids[i], pick(names)]);
    const owners = [...ids.slice(0, count), 11, 12];
    const rides = Math.floor(rand() * 9);
    for (let i = 0; i < rides; i++) Rides.push([100 + i, pick(owners), rand() < 0.15 ? 0 : 1 + Math.floor(rand() * 400)]);
  } else {
    for (let id = 1; id <= 1500; id++) Users.push([id, pick(names)]);
    for (let i = 1; i <= 2000; i++) Rides.push([i, 1 + Math.floor(rand() * 1600), Math.floor(rand() * 1000)]);
  }
  return [{ Users, Rides }];
}
